package com.example.goober;

import android.app.*;import android.os.*;import android.content.*;import android.widget.*;
public class ChatActivity extends Activity { private final MoodEngine engine=new MoodEngine(); private MemoryStore memory; private AiClient ai; private TextView history; private Button send; public void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_chat);memory=new MemoryStore(this);ai=new AiClient(this);history=findViewById(R.id.history);history.setText(memory.history());EditText input=findViewById(R.id.input);send=findViewById(R.id.send);send.setOnClickListener(v->{String text=input.getText().toString().trim();if(text.isEmpty())return;String before=history.getText().toString();history.setText(before+"\nYou: "+text+"\nGoober: thinking...\n");input.setText("");send.setEnabled(false);ai.complete(text,before,new AiClient.Callback(){public void success(String answer){append(text,answer);send.setEnabled(true);}public void error(String error){append(text,engine.reply(text)+"\n[AI unavailable: "+error+"]");send.setEnabled(true);}});});}
 private void append(String text,String answer){String h=history.getText().toString().replace("Goober: thinking...","Goober: "+answer);history.setText(h);memory.history(h);}}
